"""PlayMatch - plain-language requests generated by an LLM (Week 3).

The dataset has no search requests. For a sample of (player, game) pairs, an LLM
reads the player's review and writes the request he could have typed BEFORE
buying the game. The game is the ground truth. The prompt forbids the title, and
a leak check replaces any request that still names the game by a template.
For 30% of test/validation pairs the request also carries an explicit limit
(platform or budget), used to measure whether the model respects limits.

Two steps, because the raw reviews (2.7 GB) stay on Andrea's computer:

  1. extract (local, needs data/raw):  python -m src.queries extract --raw data/raw --data data/processed
     -> data/processed/query_sources.parquet  (small: copy it to Colab with data/processed)
  2. generate (Colab GPU):              python -m src.queries generate --data data/processed --splits test,valid
                                        python -m src.queries generate --data data/processed --splits train
     -> data/processed/queries.parquet (the second run adds the train requests to the first ones)

  3. stricter leak check (anywhere):    python -m src.queries clean --data data/processed
  Without GPU / for tests:              python -m src.queries generate --data data/processed --template
Sample sizes: --test-sample 3000 (+ all cold users), --valid-sample 2000, --train-sample 10000.
"""
from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

import numpy as np
import pandas as pd

from src.pipeline import REVIEW_FILES, find_file, read_jsonl_gz

LLM = "Qwen/Qwen2.5-1.5B-Instruct"
STOP = {"the", "a", "an", "of", "and", "for", "edition", "game", "games", "video", "nintendo", "switch", "xbox",
        "playstation", "ps4", "ps5", "pc", "one", "series", "standard", "deluxe", "collection", "with", "to", "in",
        "digital", "code", "download", "version", "complete", "remastered", "hd", "-", "&", "3ds", "ds", "wii"}
PROMPT = (
    "Here is a review a player wrote about a video game.\n"
    "Review title: {rtitle}\nReview: {rtext}\n\n"
    "Write the request this player could have typed in a game store's search box BEFORE buying this game. "
    "One sentence, first person, 8 to 25 words. Describe what they wanted: kind of game, mood, who they play with, "
    "what they dislike. Never mention the game's title, its series, its characters or its developer.{limit}\n"
    "Answer with the request only."
)


# ---------------------------------------------------------------- sampling
def choose_pairs(data: Path, test_n: int, valid_n: int, train_n: int, seed: int) -> pd.DataFrame:
    users = pd.read_parquet(data / "users.parquet")
    cold = set(users[users.is_cold].user_idx)
    test = pd.read_parquet(data / "test.parquet")
    valid = pd.read_parquet(data / "valid.parquet")
    train = pd.read_parquet(data / "train.parquet")
    warm_test = test[~test.user_idx.isin(cold)]
    parts = [
        warm_test.sample(min(test_n, len(warm_test)), random_state=seed).assign(split="test"),
        test[test.user_idx.isin(cold)].assign(split="test"),
        valid[~valid.user_idx.isin(cold)].sample(min(valid_n, (~valid.user_idx.isin(cold)).sum()),
                                                 random_state=seed).assign(split="valid"),
    ]
    liked = train[train.label == 1]
    parts.append(liked.sample(min(train_n, len(liked)), random_state=seed).assign(split="train"))
    pairs = pd.concat(parts)[["split", "user_idx", "item_idx"]].reset_index(drop=True)
    pairs["is_cold"] = pairs.user_idx.isin(cold)
    return pairs


def extract(args) -> None:
    data = Path(args.data)
    pairs = choose_pairs(data, args.test_sample, args.valid_sample, args.train_sample, args.seed)
    users = pd.read_parquet(data / "users.parquet").set_index("user_idx").user_id
    items = pd.read_parquet(data / "items.parquet").set_index("item_idx")
    pairs["user_id"] = pairs.user_idx.map(users)
    pairs["parent_asin"] = pairs.item_idx.map(items.parent_asin)
    wanted = {(u, a): k for k, (u, a) in enumerate(zip(pairs.user_id, pairs.parent_asin))}
    rtitle, rtext = [""] * len(pairs), [""] * len(pairs)
    for rec in read_jsonl_gz(find_file(Path(args.raw), REVIEW_FILES)):
        k = wanted.get((rec["user_id"], rec["parent_asin"]))
        if k is not None:
            rtitle[k], rtext[k] = rec.get("title") or "", (rec.get("text") or "")[:1500]
    pairs["review_title"], pairs["review_text"] = rtitle, rtext
    pairs["title"] = pairs.item_idx.map(items.title)
    pairs["platform"] = pairs.item_idx.map(items.platform)
    pairs["price"] = pairs.item_idx.map(items.price)
    pairs.drop(columns=["user_id", "parent_asin"]).to_parquet(data / "query_sources.parquet", index=False)
    print(pairs.groupby(["split", "is_cold"]).size().rename("pairs").to_string())
    print(f"Reviews found for {np.mean([t != '' for t in rtext]):.1%} of pairs. Saved query_sources.parquet")


# -------------------------------------------------------------- generation
def add_limits(src: pd.DataFrame, seed: int) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    src = src.copy()
    src["limit_platform"], src["limit_max_price"] = None, np.nan
    eligible = src.split.isin(["test", "valid"]).to_numpy()
    draw = rng.random(len(src))
    use_platform = eligible & (draw < 0.15) & (src.platform != "other").to_numpy()
    use_price = eligible & (draw >= 0.15) & (draw < 0.30) & src.price.notna().to_numpy()
    src.loc[use_platform, "limit_platform"] = src.loc[use_platform, "platform"]
    src.loc[use_price, "limit_max_price"] = (np.ceil(src.loc[use_price, "price"] / 10) * 10).astype(float)
    return src


def limit_sentence(row) -> str:
    if isinstance(row.limit_platform, str):
        return f" The request must say it has to run on {row.limit_platform}."
    if not np.isnan(row.limit_max_price):
        return f" The request must say the budget is under {int(row.limit_max_price)} dollars."
    return ""


def template_query(row) -> str:
    text = f"i am looking for a {row.platform.lower() if row.platform != 'other' else ''} game".replace("  ", " ")
    if isinstance(row.limit_platform, str):
        text += f" that runs on {row.limit_platform}"
    if not np.isnan(row.limit_max_price):
        text += f" under {int(row.limit_max_price)} dollars"
    return text


# Common words of game titles that a request may use without naming the game.
GENERIC = {"adventure", "adventures", "world", "worlds", "racing", "racer", "race", "sports", "sport", "party",
           "legend", "legends", "hero", "heroes", "quest", "battle", "battles", "war", "wars", "dance", "music",
           "fitness", "puzzle", "puzzles", "farm", "farming", "simulator", "simulation", "fighter", "fighting",
           "shooter", "star", "stars", "super", "ultimate", "monster", "monsters", "hunter", "hunters", "city",
           "island", "kingdom", "night", "dark", "black", "space", "zombie", "zombies", "football", "soccer",
           "basketball", "baseball", "hockey", "golf", "tennis", "chess", "cards", "card", "kids", "family",
           "story", "tales", "life", "time", "dead", "fantasy", "pack", "bundle", "season", "play", "player",
           "players", "online", "game", "games", "relaxing", "horror", "builder", "building", "survival", "magic"}


def leaks_title(query: str, title: str) -> bool:
    """True if the request names the game: one distinctive word of the title, or two title words."""
    q = set(re.findall(r"[a-z0-9]+", str(query).lower()))
    words = [w for w in re.findall(r"[a-z0-9]+", str(title).lower()) if w not in STOP and len(w) > 2]
    if not words:
        return False
    if any(len(w) >= 4 and w not in GENERIC and w in q for w in words):
        return True
    return sum(w in q for w in words) >= 2


def load_queries(data: Path) -> pd.DataFrame:
    """Requests used for training and evaluation: LLM requests that passed the leak check.
    (Template requests mention the game's platform, so they are kept out; tests without LLM use them.)"""
    q = pd.read_parquet(Path(data) / "queries.parquet")
    llm = q[q.source == "llm"]
    if len(llm):
        return llm.reset_index(drop=True)
    print("No LLM requests found: using template requests (tests only)")
    return q


def clean(args) -> None:
    """Re-run the (stricter) leak check on requests already generated, without regenerating them."""
    data = Path(args.data)
    q = pd.read_parquet(data / "queries.parquet")
    titles = pd.read_parquet(data / "items.parquet").set_index("item_idx").title
    is_llm = q.source == "llm"
    leak = is_llm & np.array([leaks_title(qq, titles.get(i, "")) for qq, i in zip(q["query"], q.item_idx)])
    q.loc[leak, "source"] = "leak_removed"
    q.to_parquet(data / "queries.parquet", index=False)
    kept = q[q.source == "llm"]
    print(f"Stricter leak check: {int(leak.sum()):,} more requests removed. Kept for training/evaluation: "
          f"{len(kept):,} {kept.split.value_counts().to_dict()} (cold in test: "
          f"{int(kept[(kept.split == 'test') & kept.is_cold].shape[0]):,})")
    for r in q[leak].head(5).itertuples():
        print(f"  removed: [{titles.get(r.item_idx, '')[:40]}] -> {r.query[:100]}")


def generate(args) -> None:
    data = Path(args.data)
    src = add_limits(pd.read_parquet(data / "query_sources.parquet"), args.seed)
    splits = args.splits.split(",")
    src = src[src.split.isin(splits)]
    src = src.sort_values("split", key=lambda s: s.map({"test": 0, "valid": 1, "train": 2})).reset_index(drop=True)
    out_path = data / "queries.parquet"
    print(f"Generating {len(src):,} requests for splits {splits}")
    queries = [None] * len(src)
    if args.template:
        queries = [template_query(r) for r in src.itertuples()]
        source = ["template"] * len(src)
    else:
        import torch
        from transformers import AutoModelForCausalLM, AutoTokenizer
        tok = AutoTokenizer.from_pretrained(args.model, padding_side="left")
        model = AutoModelForCausalLM.from_pretrained(args.model, torch_dtype=torch.float16, device_map="auto")
        torch.manual_seed(args.seed)
        prompts = []
        for r in src.itertuples():
            msg = PROMPT.format(rtitle=r.review_title, rtext=r.review_text or "(no text)", limit=limit_sentence(r))
            prompts.append(tok.apply_chat_template([{"role": "user", "content": msg}], tokenize=False,
                                                   add_generation_prompt=True))
        for start in range(0, len(prompts), args.batch):
            batch = tok(prompts[start: start + args.batch], return_tensors="pt", padding=True).to(model.device)
            with torch.no_grad():
                gen = model.generate(**batch, max_new_tokens=48, do_sample=True, temperature=0.7, top_p=0.9,
                                     pad_token_id=tok.eos_token_id)
            texts = tok.batch_decode(gen[:, batch.input_ids.shape[1]:], skip_special_tokens=True)
            for k, t in enumerate(texts):
                queries[start + k] = t.strip().split("\n")[0].strip().strip('"').strip()[:300]
            if (start // args.batch) % 20 == 0:
                print(f"  {start + len(texts):,}/{len(prompts):,} requests", flush=True)
        source = ["llm"] * len(src)

    src["query"], src["source"] = queries, source
    leak = np.array([leaks_title(q, t) or not q for q, t in zip(src["query"], src["title"])])
    src.loc[leak, "query"] = [template_query(r) for r in src[leak].itertuples()]
    src.loc[leak, "source"] = "template_after_leak"
    keep = ["split", "user_idx", "item_idx", "is_cold", "query", "source", "limit_platform", "limit_max_price"]
    new = src[keep]
    if out_path.exists():  # keep the requests already generated for the other splits
        old = pd.read_parquet(out_path)
        new = pd.concat([old[~old.split.isin(splits)], new], ignore_index=True)
    new.to_parquet(out_path, index=False)
    summary = {"pairs": len(new), "by_split": new.split.value_counts().to_dict(),
               "source": new.source.value_counts().to_dict(),
               "with_platform_limit": int(new.limit_platform.notna().sum()),
               "with_budget_limit": int(new.limit_max_price.notna().sum())}
    Path(args.out).mkdir(exist_ok=True)
    (Path(args.out) / "queries_stats.json").write_text(json.dumps(summary, indent=2))
    print(json.dumps(summary, indent=2))
    print("Examples:")
    for r in src.head(5).itertuples():
        print(f"  [{r.title[:40]}] -> {r.query}")
    print(f"Saved {out_path}")


def main() -> None:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="step", required=True)
    c = sub.add_parser("clean")
    c.add_argument("--data", default="data/processed")
    e = sub.add_parser("extract")
    e.add_argument("--raw", default="data/raw")
    g = sub.add_parser("generate")
    g.add_argument("--model", default=LLM)
    g.add_argument("--batch", type=int, default=48)
    g.add_argument("--template", action="store_true", help="no LLM: template requests (tests only)")
    g.add_argument("--splits", default="test,valid,train", help="e.g. test,valid first, then train")
    g.add_argument("--out", default="results")
    for p in (e, g):
        p.add_argument("--data", default="data/processed")
        p.add_argument("--seed", type=int, default=0)
    e.add_argument("--test-sample", type=int, default=3000)
    e.add_argument("--valid-sample", type=int, default=2000)
    e.add_argument("--train-sample", type=int, default=10000)
    args = ap.parse_args()
    {"extract": extract, "generate": generate, "clean": clean}[args.step](args)


if __name__ == "__main__":
    main()
